import itertools

def is_costas(perm):
    n = len(perm)
    # Check all pairs (i,j) with j>i
    seen = set()
    for i in range(n):
        for j in range(i+1, n):
            dr = perm[j] - perm[i]
            dc = j - i
            # vector is (dr, dc)
            if (dr, dc) in seen:
                return False
            seen.add((dr, dc))
    return True

n = 7
solutions = []
# x[1] = 1
for perm in itertools.permutations(range(n)):
    if perm[1] != 1:
        continue
    if is_costas(perm):
        solutions.append(perm)

print(f"Found {len(solutions)} solutions with x[1]=1")
for sol in solutions:
    print(sol)
